import { PlaneGeometry, Mesh, Object3D } from 'three/webgpu';
import { MeshBasicNodeMaterial, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { position, rotation, scale, assets, atlas } = config;
  const { imageUrl } = assets;

  // Load texture (cached)
  const tex = ctx.textureLoader.load(imageUrl);

  // Compute aspect ratio from atlas source rect
  const srcW = atlas?.sourceRect?.width ?? 512;
  const srcH = atlas?.sourceRect?.height ?? 320;
  const aspect = srcW / srcH; // 1.6

  // Geometry: width = 1, height = 1 / aspect
  const geometry = new PlaneGeometry(1, 1 / aspect);

  // Material with texture node
  const material = new MeshBasicNodeMaterial();
  material.mapNode = texture(tex);

  // Apply atlas UV offset if needed (assuming atlas size same as source rect)
  // If atlas is larger, compute offset/repeat from atlas.offsetX, atlas.offsetY, atlas.totalWidth, atlas.totalHeight.
  // Here we assume simple case: texture is exactly the source region.
  if (atlas && atlas.sourceRect) {
    const { x, y, width, height } = atlas.sourceRect;
    // If we had total atlas dimensions, we would set:
    // const totalW = atlas.totalWidth ?? width;
    // const totalH = atlas.totalHeight ?? height;
    // tex.offset.x = x / totalW;
    // tex.offset.y = y / totalH;
    // tex.repeat.x = width / totalW;
    // tex.repeat.y = height / totalH;
    // For simplicity, assume no atlas slicing.
  }

  const mesh = new Mesh(geometry, material);
  mesh.position.set(position.x, position.y, position.z);
  mesh.rotation.set(rotation.x, rotation.y, rotation.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // Billboard update handler
  mesh.userData.handlers = {
    update: (time, camera) => {
      if (camera) {
        mesh.lookAt(camera.position);
      }
    },
    cleanup: () => {
      geometry.dispose();
      material.dispose();
      // Do not dispose shared texture
    }
  };

  return mesh;
}
